import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        int k = sc.nextInt();

        List<Integer> digits = new ArrayList<>();
        while (n > 0) {
            digits.add((int)(n % k));
            n /= k;
        }

        int sz = k + 1;
        long[][] mat = new long[sz][sz];
        for (int j = 0; j <= k; ++j) {
            mat[0][j] = 1;
            mat[j][j] = 1;
        }

        // Matrix multiplication
        long[][] matmul(long[][] A, long[][] B) {
            long[][] C = new long[sz][sz];
            for (int i = 0; i < sz; ++i)
                for (int j = 0; j < sz; ++j)
                    for (int t = 0; t < sz; ++t)
                        C[i][j] = (C[i][j] + A[i][t] * B[t][j]) % MOD;
            return C;
        }

        // Matrix exponentiation
        long[][] matpow(long[][] base, long e) {
            long[][] res = new long[sz][sz];
            for (int i = 0; i < sz; ++i) res[i][i] = 1;
            while (e > 0) {
                if ((e & 1) == 1) res = matmul(res, base);
                base = matmul(base, base);
                e >>= 1;
            }
            return res;
        }

        // Function jia
        long[][] jia(long[][] x, int d) {
            long[][] ret = new long[sz][sz];
            for (int i = 0; i <= k; ++i)
                for (int j = 0; j <= k; ++j) {
                    int ni = (i + d) % k;
                    int nj = (j + d) % k;
                    if (i == k) ni = k;
                    if (j == k) nj = k;
                    ret[ni][nj] = x[i][j];
                }
            return ret;
        }

        long[][] A = new long[sz][sz];
        for (int j = 0; j <= k; ++j) A[0][j] = 1;
        for (int j = 0; j <= k; ++j) A[j][j] = 1;

        long[][] baseA = A;
        long[][] ansA = A;

        long[][] ans = new long[sz][sz];
        for (int i = 0; i < sz; ++i) ans[i][i] = 1;

        long idx = 0;
        for (int i = digits.size() - 1; i >= 0; --i) {
            int digit = digits.get(i);
            for (int j = 0; j < digit; ++j) {
                ans = matmul(ans, jia(baseA, (j + (int)idx) % k));
            }
            idx = (idx + digit) % k;
        }

        long total = 0;
        for (int i = 0; i <= k; ++i) {
            total = (total + ans[i][k]) % MOD;
        }
        System.out.println(total);
        sc.close();
    }
}
